// Models derived from the backend's OpenAPI contract (src/api/schema.d.ts, generated by `npm run gen:api`).
import type { components } from './schema';

type Schemas = components['schemas'];
/** springdoc marks every field optional; the API always sends them (nullable ones are typed explicitly below). */
type Model<K extends keyof Schemas> = Required<Schemas[K]>;

export type User = Model<'UserView'>;
export type TokenResponse = Model<'TokenResponse'> & { user: User };
export type Wallet = Model<'WalletResponse'>;
export type Transaction = Model<'TransactionView'>;
export type Bet = Model<'BetView'> & { settledAt: string | null };
export type Selection = Omit<Model<'SelectionView'>, 'odds' | 'result'> & { odds: number | null; result: string | null };
export type Market = Omit<Model<'MarketView'>, 'selections' | 'line' | 'suspendReason'> & {
  selections: Selection[];
  line: number | null;
  suspendReason: string | null;
};
export type SpinResult = Model<'SpinResult'> & { winningLines: Model<'LineView'>[] };
export type SlotState = Model<'StateView'>;
export type BonusPick = Model<'BonusPickResult'> & { revealedBoard: number[] | null };
export type PokerTableInfo = Model<'TableInfo'>;
export type SlotRound = Model<'RoundView'>;
export type Fairness = Model<'FairnessView'>;
export type ChatMessage = Model<'MessageView'>;
export type HandHistory = Model<'HandHistoryView'>;
export type SessionInfo = Model<'SessionRow'>;

export interface Page<T> {
  items: T[];
  nextCursor: string | null;
}

/** Normalized match state produced by the watcher. */
export interface MatchState {
  elapsed_s: number;
  net_worth: [number, number];
  objectives_alive: [number, number];
  objectives_mask: [number, number];
  spectators: number;
  winning_team: number | null;
}

export interface Team {
  name: string;
  side: 1 | 2;
  isWinner: boolean | null;
}

export interface Match {
  id: string;
  externalId: string;
  game: string;
  status: 'LIVE' | 'STALE' | 'ENDED' | 'REVIEW' | 'SETTLED' | 'VOID';
  startsAt: string;
  endedAt: string | null;
  state: Partial<MatchState>;
  teams: Team[];
  markets: Market[];
  chatRoomId: string | null;
  reviewReason: string | null;
  /** Rosters, with names and rank badges where the watcher has them. */
  players?: LivePlayer[];
  meta?: { region?: string; match_mode?: number; game_mode?: number; match_score?: number };
}

export interface MatchEventView {
  id: number;
  type: string;
  data: Record<string, unknown>;
  occurredAt: string;
}

export interface OddsPoint {
  selectionId: string;
  odds: number;
  recordedAt: string;
}

export interface MatchDetail {
  match: Match;
  events: MatchEventView[];
  oddsHistory: OddsPoint[];
}

export interface AppConfig {
  currencyMode: 'PLAY_MONEY' | 'REAL_MONEY';
  tokenFiatRate: number;
  fiatCurrency: string;
  minStakeTokens: number;
  maxStakeTokens: number;
  licensedCountries: string[];
}

export type KycStatus = 'NONE' | 'PENDING' | 'VERIFIED' | 'REJECTED';

export interface KycCheck {
  check: string;
  outcome: 'PASS' | 'REVIEW' | 'FAIL';
  message: string;
}

export interface KycSubmission {
  id: string;
  userId: string;
  username: string;
  firstName: string;
  lastName: string;
  dateOfBirth: string;
  documentType: 'PASSPORT' | 'ID_CARD' | 'DRIVING_LICENCE';
  documentCountry: string;
  documentNumberLast4: string;
  documentExpiry: string;
  status: 'PENDING' | 'APPROVED' | 'REJECTED';
  decidedBy?: 'AUTO' | 'ADMIN';
  checks: KycCheck[];
  reason?: string;
  createdAt: string;
  decidedAt?: string;
}

export interface KycInfo {
  status: KycStatus;
  canWithdraw: boolean;
  /** Absent once verified (no cap). */
  depositCapTokens?: number;
  depositedTokens?: number;
  latest?: KycSubmission;
}

export interface Limit {
  limitType: 'deposit' | 'loss' | 'wager';
  period: 'daily' | 'weekly' | 'monthly';
  amountTokens: number | null;
  usedTokens: number;
  pendingAmountTokens?: number;
  pendingFrom?: string;
}

export interface SlotGame {
  id: string;
  name: string;
  rows: number;
  columns: number;
  paylines: number[][];
  symbols: Record<string, { name: string; type: string; pays: Record<string, number> }>;
  reels: string[][];
  scatterPays: Record<string, number>;
  freeSpinsPerTrigger: number;
  minBetPerLine: number;
  maxBetPerLine: number;
}

// ---------------------------------------------------------------- poker (chips are minor units)

export interface PokerSeat {
  seatNo: number;
  userId?: string;
  username?: string;
  stack?: number;
  currentBet?: number;
  status?: 'ACTIVE' | 'FOLDED' | 'ALL_IN' | 'SITTING_OUT';
  inHand?: boolean;
  sittingOut?: boolean;
  connected?: boolean;
  cards?: string[];
}

export interface HandResult {
  handNumber: number;
  board: string[];
  rake: number;
  winnings: Record<string, number>;
  contributions: Record<string, number>;
  shown: Record<string, { cards: string[]; handRank: string }>;
  showdown: boolean;
}

export interface PokerPublicState {
  tableId: string;
  name: string;
  smallBlind: number;
  bigBlind: number;
  maxSeats: number;
  handNumber: number;
  handInProgress: boolean;
  round: 'PRE_FLOP' | 'FLOP' | 'TURN' | 'RIVER' | 'SHOWDOWN' | null;
  board: string[];
  pot: number;
  currentHighBet: number;
  dealerSeat: number;
  turnSeat: number;
  turnDeadline: string | null;
  seats: PokerSeat[];
  lastResult?: HandResult;
}

export interface LegalActions {
  canCheck: boolean;
  toCall: number;
  canRaise: boolean;
  raiseType: 'BET' | 'RAISE';
  minRaiseTo: number;
  maxRaiseTo: number;
}

export interface PokerPrivateState {
  tableId: string;
  seated: boolean;
  seatNo?: number;
  holeCards?: string[];
  sittingOut?: boolean;
  legalActions?: LegalActions;
}

/** One Deposited event from the Sepolia cashier contract, as the core sees it. */
export interface EthDeposit {
  id: string;
  txHash: string;
  fromAddress: string;
  amountEth: string;
  amountTokens: number | null;
  status: 'credited' | 'unlinked' | 'held';
  holdReason: string | null;
  blockNumber: number;
  createdAt: string;
}

/** A withdrawal to the linked MetaMask address, paid by the cashier contract. */
export interface EthWithdrawal {
  id: string;
  toAddress: string;
  amountTokens: number;
  amountEth: string;
  /** pending: queued · sent: waiting for blocks · confirmed: paid · failed: refunded · review: an admin checks it */
  status: 'pending' | 'sent' | 'confirmed' | 'failed' | 'review';
  txHash: string | null;
  error: string | null;
  createdAt: string;
  finishedAt: string | null;
}

/** GET /api/wallet/eth: MetaMask + Sepolia settings and this player's link, deposits and withdrawals. */
export interface EthStatus {
  enabled: boolean;
  chainId: number;
  contractAddress: string | null;
  tokensPerEth: number;
  confirmations: number;
  linkedAddress: string | null;
  deposits: EthDeposit[];
  withdrawalsEnabled: boolean;
  withdrawMinTokens: number;
  withdrawMaxTokens: number;
  withdrawals: EthWithdrawal[];
}

// ---- Live matches page and realtime map (watcher directory, deadlock-bot frames) ----

/** A player as the live directory knows them; name and badge are null until deadlock-api has them. */
export interface LivePlayer {
  account_id: number;
  /** 0 = Hidden King (amber), 1 = Archmother (sapphire). */
  team: 0 | 1;
  hero_id: number;
  name: string | null;
  avatar: string | null;
  /** Rank badge: tier * 10 + subrank (105 = Ascendant V). */
  badge: number | null;
}

export type MatchMode = 'ranked' | 'unranked' | 'private' | 'bots' | 'placement' | 'other';
export type GameMode = 'normal' | 'street_brawl' | 'other';

/** One match of the in-game Watch tab (GET /api/live/directory). */
export interface LiveMatchSummary {
  match_id: string;
  start_time: number;
  elapsed_s: number;
  match_mode: MatchMode;
  game_mode: GameMode;
  region: string | null;
  spectators: number;
  match_score: number;
  net_worth: [number, number];
  objectives_alive: [number, number];
  winning_team: number | null;
  team_badges: [number | null, number | null];
  badge: number | null;
  /** The watcher tracks it: it has betting markets. */
  tracked: boolean;
  players: LivePlayer[];
}

export interface LiveDirectory {
  updated_at: number | null;
  source: string | null;
  total: number;
  rank_spread: { tier: number; matches: number }[];
  matches: LiveMatchSummary[];
  /** Deadlock match id → our match id, for matches with markets. */
  bettable: Record<string, string>;
}

export interface LiveAssets {
  heroes: Record<string, { name: string; icon: string | null; minimap: string | null; color: [number, number, number] | null }>;
  ranks: Record<string, { name: string; image: string | null; color: string | null }>;
  items: Record<string, { name: string; image: string | null; tier: number | null; slot: string | null }>;
  /** Heroes' own abilities (missing in assets the watcher cached before abilities were added). */
  abilities?: Record<string, { name: string; image: string | null }>;
  map: {
    radius: number;
    image: string | null;
    /** The ziplines; their points have heights (z) in assets the watcher made since zipline heights were added. */
    lanes: { color: string; points: [x: number, y: number, z?: number][] }[];
    /** Neutral camps by kind ("vault" is a Sinner's Sacrifice); missing in assets cached before camps were added. */
    camps?: { kind: CampKind; x: number; y: number }[];
    urn_spawns?: [number, number][];
    urn_pads?: [number, number][];
    rift_spots?: [number, number][];
  };
}

export type CampKind = 'weak' | 'medium' | 'strong' | 'vault';

export interface WatchAccess {
  allowed: boolean;
  reason: 'ADMIN' | 'PREMIUM' | 'OPEN' | 'STAKE' | 'LOGIN_REQUIRED' | 'STAKE_REQUIRED';
  minStakeTokens: number;
  stakedTokens: number;
}

/** GET /api/live/matches/{deadlockMatchId} */
export interface LiveMatchInfo {
  match: LiveMatchSummary | null;
  bettableMatchId: string | null;
  watch: WatchAccess;
}

export interface FramePlayer {
  slot: number;
  account_id: number;
  hero_id: number;
  team: 0 | 1;
  level: number;
  net_worth: number;
  kills: number;
  deaths: number;
  assists: number;
  alive: boolean;
  respawn_in_s: number | null;
  ult_ready: boolean;
  items: number[];
  /** The four abilities in slot order (the ultimate last); missing in frames from older bots. */
  abilities?: FrameAbility[];
  x: number | null;
  y: number | null;
  /**
   * Height of the hero's feet, in world units like x and y (streets are at about 250–500, bridges and roofs higher,
   * tunnels lower); missing in frames from older bots.
   */
  z?: number | null;
  hp: number | null;
  max_hp: number | null;
  /** Unspent souls. */
  souls?: number | null;
  last_hits?: number | null;
  denies?: number | null;
  hero_damage?: number | null;
  objective_damage?: number | null;
}

export interface FrameAbility {
  id: number;
  unlocked: boolean;
  /** Ability points in it, 0 to 3. */
  tier: number;
}

/** A neutral camp's timer; the kind comes from the map assets (matched by position). */
export interface FrameCamp {
  id: number;
  x: number;
  y: number;
  /** Height of the camp's floor, like a hero's z; missing in frames from older bots (as are the other markers' z). */
  z?: number | null;
  /** Seconds until it is back; null while it is up. */
  respawn_in_s: number | null;
}

/** A Sinner's Sacrifice that still has health. */
export interface FrameSinner {
  x: number;
  y: number;
  z?: number | null;
  hp: number;
  max_hp: number;
}

export type ObjectiveKind = 'guardian' | 'walker' | 'base_guardian' | 'patron' | 'patron_core' | 'midboss';

export interface FrameObjective {
  id: number;
  kind: ObjectiveKind;
  team: 0 | 1 | null;
  lane: number | null;
  x: number;
  y: number;
  /** Height of its feet (the Mid-Boss stands in its pit, at about -830). */
  z?: number | null;
  hp: number;
  max_hp: number;
}

export type FrameEvent =
  | { type: 'kill'; time_s: number; victim: number; killer: number | null; assisters: number[] }
  | { type: 'purchase'; time_s: number; account_id: number; item_id: number }
  | { type: 'level_up'; time_s: number; account_id: number; level: number }
  | { type: 'ability_unlocked'; time_s: number; account_id: number; ability_id: number }
  /** An ability point put into an ability: tier 1 to 3. */
  | { type: 'ability_upgraded'; time_s: number; account_id: number; ability_id: number; tier: number }
  | { type: 'objective_destroyed'; time_s: number; kind: ObjectiveKind; team: 0 | 1 | null; lane: number | null }
  /** The Mid-Boss fell to `killer` (a hero, when it was one) of `team`. */
  | { type: 'midboss_killed'; time_s: number; team: 0 | 1 | null; killer?: number | null }
  | { type: 'urn_spawned'; time_s: number }
  | { type: 'urn_picked_up' | 'urn_dropped'; time_s: number; account_id: number }
  | { type: 'urn_delivered'; time_s: number; account_id: number; team: 0 | 1 }
  | { type: 'rift_appeared' | 'rift_opened' | 'rift_closed'; time_s: number }
  | { type: 'rift_captured'; time_s: number; team: 0 | 1 };

/** The Soul Urn while it is in play: on the ground, or carried (it then follows the carrier). */
export interface FrameUrn {
  x: number;
  y: number;
  /** On the ground its own height, carried its carrier's. */
  z?: number | null;
  carrier: number | null;
  /** Where it has to be taken, once someone picked it up. */
  delivery: [number, number] | null;
  delivery_z?: number | null;
  /** Souls it gives the team that delivers it. */
  value?: number | null;
}

/** The Unstable Rift: appearing on a side-lane bridge, then open as a capture point. */
export interface FrameRift {
  x: number;
  y: number;
  z?: number | null;
  open: boolean;
  /** Seconds until an appearing rift opens. */
  opens_in_s?: number | null;
  /** Capture progress per team (Hidden King first), 0 to 1. */
  progress: [number, number];
  capturers: [number, number];
  /** Both teams are on the point, so neither makes progress. */
  contested?: boolean;
  /** Hero ids of each team's players on the point. */
  heroes?: [number[], number[]];
  /** Seconds until an open rift closes uncaptured. */
  closes_in_s: number | null;
}

/** What a bridge power-up gives, by the game's names: fire rate and clip size, health, spirit power, or speed. */
export type PowerupKind = 'gun' | 'survival' | 'casting' | 'movement';

/** A bridge power-up waiting to be picked up. */
export interface FramePowerup {
  x: number;
  y: number;
  z?: number | null;
  /** Its kind; absent in frames from bots older than kinds, null when the broadcast doesn't show it. */
  kind?: PowerupKind | null;
}

/** One realtime map frame (WebSocket topic watch:{deadlockMatchId}, type LIVE_FRAME), about twice a second. */
export interface LiveFrame {
  match_id: string;
  tick: number;
  game_time_s: number | null;
  paused: boolean;
  /** How far the broadcast runs behind the real game. */
  delay_s: number;
  /** Minimap world bounds: [minX, minY, maxX, maxY]. */
  minimap: [number, number, number, number] | null;
  objectives_mask: [number, number] | null;
  net_worth: [number, number];
  winning_team: number | null;
  players: FramePlayer[];
  objectives: FrameObjective[];
  /** Absent in frames from bots older than the urn and rift. */
  urn?: FrameUrn | null;
  rift?: FrameRift | null;
  /** Absent in frames from bots older than the camps. */
  camps?: FrameCamp[];
  /** Seconds until the Mid-Boss is back, while it is dead. */
  midboss_respawn_in_s?: number | null;
  /** Height of the Mid-Boss's spot in its pit, for that countdown. */
  midboss_z?: number | null;
  sinners?: FrameSinner[];
  /** Bridge power-ups waiting to be picked up. */
  powerups?: FramePowerup[];
  events: FrameEvent[];
  received_at: number;
}
